/**
 * Shared centered light surface for the a11y stories below so the field and
 * its focus ring / helper region read clearly.
 */
const A11yFrame = ({ children }: { children: React.ReactNode }) => (
  <div
    style={{
      backgroundColor: '#f8fafc',
      minHeight: '100vh',
      padding: '2rem',
      boxSizing: 'border-box',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
    }}
  >
    <div style={{ maxWidth: '400px', width: '100%' }}>{children}</div>
  </div>
)

/**
 * Required field — the FieldShell renders the `*` required indicator next to
 * the label (aria-hidden, decorative) AND sets `aria-required` on the input, so
 * the requirement is conveyed programmatically, not by the asterisk alone
 * (WCAG 1.3.1 / 3.3.2).
 */
export const RequiredField: Story = {
  name: 'Required (aria-required)',
  render: args => (
    <A11yFrame>
      <USDField {...args} />
    </A11yFrame>
  ),
  args: {
    label: 'Payment amount',
    initialValue: '',
    helperText: 'This field is required',
    styles: { theme: 'light', required: true },
  },
}

/**
 * Error state — a string `error` flows through FieldShell to render the message
 * with `role="alert"` + `aria-live="polite"`, links it to the input via
 * `aria-describedby`, and sets `aria-invalid="true"`. The invalidity is exposed
 * programmatically and in text, never by the border colour alone
 * (WCAG 1.4.1 / 3.3.1 / 4.1.2 / 4.1.3).
 */
export const ErrorState: Story = {
  name: 'Error (aria-invalid + alert)',
  render: args => (
    <A11yFrame>
      <USDField {...args} />
    </A11yFrame>
  ),
  args: {
    label: 'Amount',
    initialValue: '0.00',
    error: 'Amount must be greater than $0.00',
    styles: { theme: 'light' },
  },
}

/**
 * Keyboard-operable steppers. Proves the increment/decrement buttons respond to
 * Enter (previously they were wired to `onMouseDown` only, so keyboard users
 * could focus but never activate them) and that Arrow Up / Arrow Down on the
 * input adjust the value — the native number-input affordance. The play
 * function drives real keyboard events and asserts the value changes; it leaves
 * focus in the field so the Chromatic snapshot also captures the focus ring.
 * WCAG 2.1.1 / 2.4.7.
 */
export const KeyboardOperableSteppers: Story = {
  name: 'Keyboard steppers (Enter / Arrows)',
  render: args => (
    <A11yFrame>
      <USDField {...args} />
    </A11yFrame>
  ),
  args: {
    label: 'Amount',
    initialValue: '10.00',
    enableIncrement: true,
    incrementStep: 1,
    helperText: 'Enter/Space on the buttons; Arrow Up/Down in the field',
    styles: { theme: 'light' },
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement)
    const input = canvas.getByLabelText(/amount/i) as HTMLInputElement
    const incrementButton = canvas.getByRole('button', { name: 'increment' })
    const decrementButton = canvas.getByRole('button', { name: 'decrement' })

    // The stepper buttons must be operable from the keyboard (Enter).
    incrementButton.focus()
    await userEvent.keyboard('{Enter}')
    await waitFor(() => expect(input).toHaveValue('11.00'))

    decrementButton.focus()
    await userEvent.keyboard('{Enter}')
    await waitFor(() => expect(input).toHaveValue('10.00'))

    // Arrow Up / Down on the input itself adjust the value.
    input.focus()
    await userEvent.keyboard('{ArrowUp}{ArrowUp}')
    await waitFor(() => expect(input).toHaveValue('12.00'))

    await userEvent.keyboard('{ArrowDown}')
    await waitFor(() => expect(input).toHaveValue('11.00'))
  },
}

/**
 * Assistive-tech / voice-control / mobile-double-tap operability. Those methods
 * dispatch a bare `click` event with **no** preceding `mousedown` (a synthetic
 * activation, `detail === 0`), so a stepper wired to `onMouseDown` alone would
 * be inoperable for them even though it looks like a button. The field now also
 * handles `onClick`, gated on `detail === 0` so a real mouse click (which
 * already stepped through `onMouseDown`, `detail >= 1`) does not double-step.
 * The play function drives BOTH paths: a bare `fireEvent.click` (the AT path —
 * must step) and a full `userEvent.click` (a real pointer press — must step
 * exactly once, never twice). WCAG 2.1.1 / 4.1.2.
 */
export const ClickOperableSteppers: Story = {
  name: 'Click-operable steppers (AT / voice)',
  render: args => (
    <A11yFrame>
      <USDField {...args} />
    </A11yFrame>
  ),
  args: {
    label: 'Amount',
    initialValue: '10.00',
    enableIncrement: true,
    incrementStep: 1,
    helperText: 'Operable by a synthetic click, not only a pointer press',
    styles: { theme: 'light' },
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement)
    const input = canvas.getByLabelText(/amount/i) as HTMLInputElement
    const incrementButton = canvas.getByRole('button', { name: 'increment' })
    const decrementButton = canvas.getByRole('button', { name: 'decrement' })

    // AT / voice-control / mobile screen-reader double-tap: a bare click with
    // detail === 0 and no preceding mousedown MUST still step the value.
    fireEvent.click(incrementButton)
    await waitFor(() => expect(input).toHaveValue('11.00'))

    fireEvent.click(decrementButton)
    await waitFor(() => expect(input).toHaveValue('10.00'))

    // A real mouse click (mousedown + mouseup + click, detail >= 1) steps
    // EXACTLY once — the click path must not double-count the pointer press.
    await userEvent.click(incrementButton)
    await waitFor(() => expect(input).toHaveValue('11.00'))
  },
}

/**
 * Min/max range exposed to assistive tech. This is a free-form currency text
 * input (deliberately `type="text"` + `inputMode="decimal"`, NOT
 * `role="spinbutton"`), so it exposes no `aria-valuemin`/`aria-valuemax`. When
 * `min`/`max` are constrained the field instead references a visually-hidden
 * description via `aria-describedby`, so a screen-reader user hears the allowed
 * bounds on focus even when the consumer supplies **no** helperText. The play
 * function deliberately renders WITHOUT helperText — the pre-fix field left the
 * range invisible to assistive tech in exactly that case (WCAG 1.3.1 / 4.1.2).
 */
export const RangeExposedToAT: Story = {
  name: 'Min/max range (aria-describedby)',
  render: args => (
    <A11yFrame>
      <USDField {...args} />
    </A11yFrame>
  ),
  args: {
    label: 'Amount',
    initialValue: '50.00',
    min: 0,
    max: 1000,
    enableIncrement: true,
    // NO helperText on purpose — proves the range is exposed programmatically
    // regardless of any visible hint.
    styles: { theme: 'light' },
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement)
    const input = canvas.getByLabelText(/amount/i) as HTMLInputElement

    // The allowed range must be exposed programmatically via aria-describedby,
    // even though no helperText/error is present (pre-fix: undefined).
    const describedBy = input.getAttribute('aria-describedby')
    await expect(describedBy).toBeTruthy()

    // At least one referenced node must spell out the min/max bounds.
    const referencedText = (describedBy ?? '')
      .split(/\s+/)
      .filter(Boolean)
      .map(
        refId =>
          canvasElement.ownerDocument.getElementById(refId)?.textContent ?? ''
      )
      .join(' ')
    await expect(referencedText).toMatch(/between \$0 and \$1000/i)
  },
}

/**
 * aria-describedby composition. A consumer can spread their own
 * `aria-describedby` onto `<USDField>` (e.g. to reference an external
 * instructions block). The field MERGES that reference with the Shell's
 * error/helper description instead of letting one clobber the other, so the
 * validation message stays programmatically linked to the input even when the
 * consumer adds a description of their own. The play function asserts the input
 * references BOTH the error text and the external hint (pre-fix: `{...rest}`
 * overrode the Shell's describedby in the no-range path, dropping the error
 * link). WCAG 1.3.1 / 3.3.1 / 4.1.2.
 */
export const DescribedByComposition: Story = {
  name: 'aria-describedby merge (error + external)',
  render: args => (
    <A11yFrame>
      <p id="usd-external-hint" style={{ fontSize: 12, color: '#475569' }}>
        Enter the amount from your invoice.
      </p>
      <USDField {...args} aria-describedby="usd-external-hint" />
    </A11yFrame>
  ),
  args: {
    label: 'Amount',
    initialValue: '0.00',
    error: 'Amount must be greater than $0.00',
    styles: { theme: 'light' },
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement)
    const input = canvas.getByLabelText(/amount/i) as HTMLInputElement

    const describedBy = input.getAttribute('aria-describedby')
    await expect(describedBy).toBeTruthy()

    // The consumer's own reference must survive the merge…
    await expect(describedBy).toContain('usd-external-hint')

    // …AND every referenced node together must still surface the error message
    // (the Shell's helper/error id must not have been clobbered by `{...rest}`).
    const referencedText = (describedBy ?? '')
      .split(/\s+/)
      .filter(Boolean)
      .map(
        refId =>
          canvasElement.ownerDocument.getElementById(refId)?.textContent ?? ''
      )
      .join(' ')
    await expect(referencedText).toMatch(/greater than \$0\.00/i)
    await expect(referencedText).toMatch(/from your invoice/i)
  },
}

/**
 * Accessible name for a LABEL-LESS field. A bare currency input (a toolbar or
 * data-table cell rendered with no visible `label`) is anonymous to screen
 * readers — a placeholder is NOT an accessible name. Passing `ariaLabel`
 * forwards through FieldShell, which applies it as `aria-label` on the input
 * when no visible `<label>` renders, so the field is still named (WCAG 4.1.2).
 * The play function renders WITHOUT a visible label (`label=""`) and asserts the
 * input carries the programmatic name (pre-seam: the input was unnamed).
 */
export const AriaLabelWhenLabelless: Story = {
  name: 'Aria-label (label-less)',
  render: args => (
    <A11yFrame>
      <USDField {...args} />
    </A11yFrame>
  ),
  args: {
    label: '',
    initialValue: '49.99',
    ariaLabel: 'Invoice amount',
    styles: { theme: 'light' },
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement)
    // getByLabelText resolves the accessible name from `aria-label` when no
    // visible <label> is present — proving the seam forwarded the name.
    const input = canvas.getByLabelText('Invoice amount')
    await expect(input).toHaveAttribute('aria-label', 'Invoice amount')
  },
}
